#!/usr/bin/env python3
"""Regenerate references/parameters.md from the bundled profiles (run after editing a profile)."""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from knc_model.profile import load_profile, list_profiles  # noqa: E402
from knc_model.util import resource_path  # noqa: E402


def fmt(v):
    if isinstance(v, (dict, list)):
        s = json.dumps(v, sort_keys=True)
        return s if len(s) < 60 else s[:57] + "..."
    return str(v)


def main():
    out = ["# Parameters", "",
           "Generated by `scripts/gen_parameters_doc.py` from `profiles/*.json`. Each parameter carries a value (or",
           "explicit unknown), unit, status (documented, measured, literature, derived, assumed, unknown, synthetic),",
           "source (document and page, or native measurement identifier) and, where relevant, alternatives and",
           "uncertainty. The engine refuses to run with an unknown parameter it needs (`missing_parameter`).", ""]
    for p in list_profiles():
        prof = load_profile(p["id"])
        top = prof.chain[-1]
        out.append("## %s%s" % (prof.id, " (SYNTHETIC)" if prof.synthetic else ""))
        out.append("")
        out.append(top.get("description", ""))
        out.append("")
        if prof.native_measurement_ids:
            out.append("Native measurement identifiers: " + "; ".join(prof.native_measurement_ids))
            out.append("")
        out.append("Calibration: %s. %s" % (prof.calibration.get("state"), prof.calibration.get("statement", "")))
        out.append("")
        own = top["parameters"]
        if top.get("extends"):
            out.append("Extends `%s`; the rows below are this profile's own values (inherited rows are not repeated)." % top["extends"])
            out.append("")
        out.append("| parameter | value | unit | status | source | alternatives / uncertainty |")
        out.append("|---|---|---|---|---|---|")
        for name in sorted(own):
            d = own[name]
            alt = ", ".join(fmt(a) for a in d.get("alternatives", []))
            unc = d.get("uncertainty", "") or d.get("note", "")
            extra = "; ".join(x for x in (("alt: " + alt) if alt else "", unc) if x)
            out.append("| `%s` | %s | %s | %s | %s | %s |" % (name, fmt(d.get("value")), d.get("unit", ""), d.get("status", ""),
                                                        (d.get("source", "") or "").replace("|", "/"), extra.replace("|", "/")))
        out.append("")
    path = resource_path("references", "parameters.md")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(out))
    print("wrote", path)


if __name__ == "__main__":
    main()
